package os.aios.agent;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
/** Production service window: copy, paste and selection survival during updates. */
public final class InteractionLocaleTests extends Instrumentation {
 android.os.LocaleList originalLocales;Object localeManager;
 void systemLocales(android.os.LocaleList locales){try{localeManager.getClass().getMethod("setSystemLocales",android.os.LocaleList.class).invoke(localeManager,locales);}catch(Exception ex){throw new RuntimeException(ex);}}
 int checks;Throwable failure;AssistantOrbService service;AssistantSelectionPanel panel;TextView selected;EditText input;String draft="";
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 void press(View view){int[] xy=new int[2];main(()->{view.getLocationOnScreen(xy);if(view instanceof EditText){xy[0]+=view.getWidth()/2-30;xy[1]+=view.getHeight()/2-25;}});long down=SystemClock.uptimeMillis();MotionEvent event=MotionEvent.obtain(down,down,MotionEvent.ACTION_DOWN,xy[0]+30,xy[1]+25,0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(event,true);event.recycle();SystemClock.sleep(900);event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,xy[0]+30,xy[1]+25,0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(event,true);event.recycle();SystemClock.sleep(800);}
 void screenshot(String name){try{android.graphics.Bitmap b=getUiAutomation().takeScreenshot();if(b!=null){try(java.io.OutputStream file=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,file);}b.recycle();}}catch(Exception ex){throw new RuntimeException(ex);}}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 void main(Runnable action){runOnMainSync(()->{try{action.run();}catch(Throwable t){failure=t;}});if(failure!=null)throw new RuntimeException(failure);}
 Object field(Object owner,String name){try{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}catch(Exception e){throw new RuntimeException(e);}}
 void invoke(String method,Class<?>[] types,Object... args){try{java.lang.reflect.Method m=AssistantOrbService.class.getDeclaredMethod(method,types);m.setAccessible(true);m.invoke(service,args);}catch(Exception e){throw new RuntimeException(e);}}
 TextView find(View view){if(view instanceof TextView&&((TextView)view).isTextSelectable()&&((TextView)view).getText().toString().contains("ACCEPTED"))return (TextView)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=g.getChildCount()-1;i>=0;i--){TextView found=find(g.getChildAt(i));if(found!=null)return found;}}return null;}
 public void onStart(){Bundle out=new Bundle();Context c=getTargetContext();android.content.ClipboardManager clipboard=c.getSystemService(android.content.ClipboardManager.class);ClipData before=null;boolean captured=false;
 try{c.startForegroundService(new Intent(c,AssistantOrbService.class).setAction("show"));Thread.sleep(1200);
  main(()->{try{Class<?> at=Class.forName("android.app.ActivityThread");Object thread=at.getDeclaredMethod("currentActivityThread").invoke(null);java.lang.reflect.Field services=at.getDeclaredField("mServices");services.setAccessible(true);for(Object candidate:((java.util.Map<?,?>)services.get(thread)).values())if(candidate instanceof AssistantOrbService)service=(AssistantOrbService)candidate;}catch(Exception e){throw new RuntimeException(e);}check(service!=null,"production orb started");panel=(AssistantSelectionPanel)field(service,"panel");input=(EditText)field(service,"input");draft=(String)field(service,"keyboardDraft");selected=find(panel);check(selected!=null,"dedicated test reply visible");});Thread.sleep(250);
  before=clipboard.getPrimaryClip();captured=true;press(selected);main(()->{out.putString("selection_state","window="+selected.hasWindowFocus()+" focus="+selected.hasFocus()+" selectable="+selected.isTextSelectable()+" range="+selected.getSelectionStart()+":"+selected.getSelectionEnd()+" attached="+selected.isAttachedToWindow());check(panel.selecting(),"production overlay native toolbar");check(selected.hasSelection(),"message selected");invoke("render",new Class<?>[]{});check(selected.isAttachedToWindow()&&selected.hasSelection(),"live render retains selection");});Thread.sleep(700);
  main(()->{selected.onTextContextMenuItem(android.R.id.selectAll);check(selected.onTextContextMenuItem(android.R.id.copy),"production copy");panel.finishSelection();invoke("setKeyboardMode",new Class<?>[]{boolean.class},true);});Thread.sleep(400);
  String copied=clipboard.getPrimaryClip().getItemAt(0).coerceToText(c).toString();check(copied.contains("ACCEPTED"),"production copied expected reply");
  main(()->{input.setText("");check(input.onTextContextMenuItem(android.R.id.paste),"production paste");check(input.getText().toString().equals(copied),"production input receives copy");});Thread.sleep(1000);screenshot("input-before");press(input);screenshot("input-after");main(()->{out.putString("input_state","focus="+input.hasFocus()+" window="+input.hasWindowFocus()+" range="+input.getSelectionStart()+":"+input.getSelectionEnd()+" keyboard="+field(service,"keyboardMode"));check(panel.selecting(),"production input menu");panel.finishSelection();input.setText(draft);});
  localeManager=c.getSystemService(android.app.LocaleManager.class);originalLocales=((android.app.LocaleManager)localeManager).getSystemLocales();getUiAutomation().adoptShellPermissionIdentity("android.permission.CHANGE_CONFIGURATION");
  main(()->{input.setText("Draft 草稿 مسودة");input.setSelection(5);});
  String[][] locales={{"en-US","Guide now"},{"zh-CN","立即引导"},{"zh-TW","立即引導"},{"ar","Guide now"}};
  for(String[] locale:locales){systemLocales(android.os.LocaleList.forLanguageTags(locale[0]));Thread.sleep(1600);main(()->{panel=(AssistantSelectionPanel)field(service,"panel");input=(EditText)field(service,"input");check(input.getText().toString().equals("Draft 草稿 مسودة"),"draft survives system language "+locale[0]);check(input.getSelectionStart()==5,"selection survives "+locale[0]);check(panel.getLayoutDirection()==(locale[0].equals("ar")?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR),"actual layout direction "+locale[0]);check(service.getString(service.getResources().getIdentifier("followup_steer","string",service.getPackageName())).equals(locale[1]),"translated action or English fallback "+locale[0]);});android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();if(bitmap!=null){try(java.io.OutputStream file=new java.io.FileOutputStream(new java.io.File(c.getFilesDir(),"interaction-locale-"+locale[0]+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,file);}bitmap.recycle();}}
  systemLocales(originalLocales);Thread.sleep(1200);main(()->{input=(EditText)field(service,"input");input.setText(draft);});
  out.putString("result","PASS "+checks+" checks");
 }catch(Throwable t){out.putString("error",android.util.Log.getStackTraceString(t));}finally{if(originalLocales!=null)try{systemLocales(originalLocales);Thread.sleep(1000);}catch(Throwable restoreError){out.putString("restore_error",restoreError.toString());}getUiAutomation().dropShellPermissionIdentity();ClipData restore=before;boolean restoreClipboard=captured;runOnMainSync(()->{if(service!=null){if(input!=null)input.setText(draft);service.stopSelf();}if(restoreClipboard){if(restore!=null)clipboard.setPrimaryClip(restore);else clipboard.clearPrimaryClip();}});finish(out.containsKey("error")?0:-1,out);}}
}
